  if(!_skyGlossaryReady) loadSkyGlossary().then(()=>{ if(templeActive&&_templeFocus&&(_templeFocus.kind==='body'||_templeFocus.kind==='sign')&&_templeFocus.pick&&_templeFocus.pick.id===pick.id) requestTempleStudy(pick); });
