  if(!raw) return null;
  let o=null; try{ o=JSON.parse(raw); }catch(e){ return null; }
  if(!o || typeof o!=='object' || Array.isArray(o) || o.v!==1) return null;   // an array, a number, a string, a future v:2 — every one of them is "no memory"
